    fun height(x: Float, z: Float, press: Float): Float {
        val u = (x - AdventureLevel.PAD.x + 0.14f) / 0.02f
        val v = (z - AdventureLevel.PAD.z + 0.14f) / 0.02f
        if (u < 0f || v < 0f || u >= 14f || v >= 14f) return 0f
        val ix=u.toInt(); val iz=v.toInt(); val tx=u-ix; val tz=v-iz
        fun sample(dx: Int, dz: Int) = heights[(iz+dz)*15+ix+dx]
        val h=(sample(0,0)*(1-tx)+sample(1,0)*tx)*(1-tz)+
            (sample(0,1)*(1-tx)+sample(1,1)*tx)*tz
        return (h - press.coerceIn(0f,1f)*0.006f*(h/0.008f).coerceIn(0f,1f)).coerceAtLeast(0f)
    }
